func LookupOuiBinaryGo(mac string) *OuiRecord {
	clean := strings.Builder{}
	for i := 0; i < len(mac); i++ {
		c := mac[i]
		if (c >= '0' && c <= '9') || (c >= 'A' && c <= 'F') { clean.WriteByte(c) } else if c >= 'a' && c <= 'f' { clean.WriteByte(c - 32) }
	}
	s := clean.String()
	if len(s) < 6 { return nil }
	pfx := s[:6]
	idx := sort.Search(len(CompiledOuiTable), func(i int) bool { return CompiledOuiTable[i].Prefix >= pfx })
	if idx < len(CompiledOuiTable) && CompiledOuiTable[idx].Prefix == pfx { return &CompiledOuiTable[idx] }
	return nil
}

func LookupPslBinaryGo(sfx string) bool {
	t := strings.ToLower(strings.TrimSpace(sfx))
	idx := sort.Search(len(CompiledPslTable), func(i int) bool { return CompiledPslTable[i].Suffix >= t })
	return idx < len(CompiledPslTable) && CompiledPslTable[idx].Suffix == t
}
